db[18]=db[18] or {}
db[18][db[18]["text"] and "text#observed20261018" or "text"]= {it="Di recente, un nuovo gruppo di ladri si aggira nei pressi di Borgolondro. Si fanno chiamare Fratellanza di Defias e sono stati avvistati oltre il fiume, a est.\nNon so cosa stiano tramando, ma di certo non è nulla di buono! Portami le loro bandane e ti ricompenserò con un'arma.",enHash={"da68ce71"}}
db[3905]=db[3905] or {}
db[3905][db[3905]["text"] and "text#observed20261018" or "text"]= {it="Ora che il raccolto è salvo, porta questo Registro dell'Uva a Fratello Neals. Gestisce le scorte di cibo e bevande di Borgolondro e sarà felice di sapere che c'è dell'uva fresca.\nLo troverai nell'abbazia, sul campanile... dove ama degustare il suo vino.",enHash={"9682fac6"}}
db[91772]=db[91772] or {}
db[91772][db[91772]["text"] and "text#observed20261018" or "text"]= {it="Bene. Prendi questo kit per seguire le tracce dei coboldi. Ti permetterà di rintracciare il coboldo che preoccupa il Maresciallo McBride.\nSegui le tracce e porta ciò che trovi al Maresciallo Dughan a Borgodoro.\nHo la sensazione che questi furfanti stiano tramando qualcosa fuori da Borgolondro. Quindi ti servirà l'aiuto di Dughan.",enHash={"79b7c12c"}}
db[92462]=db[92462] or {}
db[92462][db[92462]["text"] and "text#observed20261018" or "text"]= {it="Uno dei nostri ranger ha segnalato di recente un'infestazione di mosche cirro qui nel Boschetto di Thendal.\nPossono essere pericolose se lo sciame cresce troppo, quindi raggiungi l'estremità orientale del boschetto e sterminane quante più puoi.",enHash={"1f75375b"}}
db[92481]=db[92481] or {}
db[92481][db[92481]["text"] and "text#observed20261018" or "text"]= {it="Mentre ti occupavi dei vuldren, la nostra istruttrice dei maghi, Dorii Brightwhisper, ha lasciato questo cristallo del richiamo per te. Contiene un messaggio, quindi dagli un'occhiata. Poi troverai Dorii nell'edificio proprio alle mie spalle.",enHash={"3604062e"}}
